def nexec(statement, globals=None, locals=None, **kwargs):
    """Execute *statement* using *globals* and *locals* dictionaries as
    *global* and *local* namespace.  *statement* is transformed using
    :class:`.NapiTransformer`."""
    transformer = NapiTransformer(**kwargs)
    statement = transformer.transform(statement)
    if globals is None:
        globals = {}
    if locals is None:
        locals = {}
    code = compile(statement, '<string>', 'exec')
    return exec(code, globals, locals)

